/* Scales a 16-bit pitch value by 2^(1/12), raising it one semitone. */ s32 raisePitchOneSemitone(s32 pitch) {
    f32 scaled;
    s32 newPitch;

    scaled = (f32) (pitch & 0xFFFF) * 1.0594631f;
    newPitch = (u32) scaled;
    return newPitch & 0xFFFF;
}
